using Comet.Core;
using System.Text.Json;
internal static class CrossfireTests
{
 public static int Run(){int n=0;void C(bool ok,string why){n++;if(!ok)throw new Exception("S01: "+why);}
 var c=new CrossfireConfig();c.Validate();C(c.Enabled&&c.Participation==70&&c.Interval==.5&&c.SupportDistance==35&&c.EnemyDistance==80&&c.ContactAge==20&&c.OutdoorAngle==35&&c.IndoorAngle==20&&c.Spacing==4&&c.MaxPath==35&&c.MoveTimeout==12&&c.StallTimeout==3&&c.HoldTimeout==20&&c.Retry==4,"defaults");
 foreach(var prop in typeof(CrossfireConfig).GetProperties().Where(p=>p.PropertyType==typeof(double)))foreach(double bad in new[]{double.NaN,double.PositiveInfinity,-1,1000}){var v=new CrossfireConfig();prop.SetValue(v,bad);bool fail=false;try{v.Validate();}catch(ArgumentException){fail=true;}C(fail,"invalid "+prop.Name);}
 foreach(string key in new[]{"IndoorAngle","StallTimeout"}){var v=new CometConfig();if(key=="IndoorAngle")v.Crossfire.IndoorAngle=80;else v.Crossfire.StallTimeout=20;bool fail=false;try{v.Validate();}catch(ArgumentException){fail=true;}C(fail,"cross-field "+key);}
 C(JsonSerializer.Deserialize<CometConfig>("{}")!.Crossfire.Participation==70,"old config migration");{var v=new CometConfig();v.Crossfire.Enabled=false;v.Crossfire.Participation=25;v.Validate();var round=JsonSerializer.Deserialize<CometConfig>(JsonSerializer.Serialize(v))!;C(!round.Crossfire.Enabled&&round.Crossfire.Participation==25,"server roundtrip");}
 foreach(var roll in new[]{0d,.69999,.7,.99}){var p=new Crossfire();bool chosen=p.Begin(10,c,roll);C(chosen==(roll<.7),"participation boundary");if(!chosen)C(!p.Active&&p.RetryAt==14,"decline cooldown");else{p.Ready(1,2,3,40,12);p.Applied(true);C(!p.Trace!.Applied,"reservation is not execution");p.Moving(11,10);p.Applied(true);C(p.Trace!.Applied&&p.Trace.ValidFor<=1,"executed lease");C(p.Progress(12,.8,c)&&p.Trace.State=="holding","arrival");C(p.Check(31.99,c,"",true)&&!p.Check(32,c,"",true),"exact hold expiry");}}
 {var p=new Crossfire();p.Begin(10,c,0);C(p.Check(30,c,"",false),"source planning not aborted by COMET timeout or support loss");p.Ready(1,2,3,40,10);p.Moving(30,10);C(p.Progress(38,10,c),"no extra stall veto");C(!p.Check(42,c,"",false),"source move timeout still applies");}

 {var p=new Crossfire();p.Begin(10,c,0);C(p.Check(11.99,c,"",false)&&p.Check(12,c,"",false),"support grace exact boundary");}
 foreach(string mode in new[]{"priority","off","clock","nan"}){var p=new Crossfire();var v=new CrossfireConfig();p.Begin(10,v,0);p.Ready(1,2,3,45,5);p.Moving(10,5);p.Applied(true);if(mode=="off")v.Enabled=false;C(!p.Check(mode=="clock"?9:mode=="nan"?double.NaN:11,v,mode=="priority"?"urgent":"",true)&&!p.Trace!.Applied&&!p.Trace.Reserved,"release "+mode);}
 {var board=new CrossfireClaims();C(board.Reserve("a",0,0,0,4,10)&&board.Reserve("b",4,0,0,4,10)&&board.Reserve("c",8,0,0,4,10)&&board.Count==3,"three movers allowed");C(!board.Reserve("d",3,0,0,4,10),"spacing collision");C(board.Renew("a",11)&&board.Free("d",8,0,0,4,210)&&board.Count==1,"expired owners swept");C(board.Reserve("b",4,0,0,4,210),"expired same owner may reserve again");board.Release("a");C(board.Count==1,"release only owner");C(!board.Renew("b",9)&&board.Count==0,"clock rollback clears raid-local board");C(!board.Free("x",double.NaN,0,0,4,10),"invalid point fails closed");}
 {var board=new CrossfireClaims();C(board.Reserve("a",0,0,0,4,10,"squad-a")&&!board.Reserve("b",0,0,0,4,10,"squad-b"),"source global destination claims");C(!board.Reserve("c",0,0,0,4,10,"squad-a"),"same squad still separates destinations");}
 C(CrossfireGeometry.InLane(0,0,5,0,0,0,0,0,10),"inside firing corridor");C(!CrossfireGeometry.InLane(2,0,5,0,0,0,0,0,10),"outside lane");C(!CrossfireGeometry.InLane(0,3,5,0,0,0,0,0,10),"different floor");C(!CrossfireGeometry.InLane(0,0,-1,0,0,0,0,0,10)&&!CrossfireGeometry.InLane(0,0,11,0,0,0,0,0,10),"finite segment only");
 Comet.Api.Decisions.SetCrossfire("test","COMET:CrossfireMoving");C(Comet.Api.Decisions.GetCrossfireDecision("test")=="COMET:CrossfireMoving","optional RR API");Comet.Api.Decisions.Clear();C(Comet.Api.Decisions.GetCrossfireDecision("test")=="","API raid cleanup");
 C(CrossfireGeometry.RequiredAngle(35,0,80,24)<18&&CrossfireGeometry.RequiredAngle(35,0,80,24)>=10,"80m contact does not demand impossible 35 degree angle in a 24m radius");
 C(CrossfireGeometry.RequiredAngle(35,0,20,24)==35,"near contact retains preferred angle");
 C(CrossfireGeometry.RequiredAngle(35,40,80,24)>=50,"existing separation still requires useful improvement");
 Console.WriteLine($"{n} S01 policy/config/geometry checks passed");return n;}
}
